1	import type { XY } from '../../Point';
2	import type { TBBox } from '../../typedefs';
3	
4	/**
5	 * Calculates bounding box (left, top, width, height) from given `points`
6	 * @param {XY[]} points
7	 * @return {Object} Object with left, top, width, height properties
8	 */
9	export const makeBoundingBoxFromPoints = (points: XY[]): TBBox => {
10	  let left = 0,
11	    top = 0,
12	    width = 0,
13	    height = 0;
14	
15	  for (let i = 0, len = points.length; i < len; i++) {
16	    const { x, y } = points[i];
17	    if (x > width || !i) width = x;
18	    if (x < left || !i) left = x;
19	    if (y > height || !i) height = y;
20	    if (y < top || !i) top = y;
21	  }
22	
23	  return {
24	    left,
25	    top,
26	    width: width - left,
27	    height: height - top,
28	  };
29	};
