12	import { makeBoundingBoxFromPoints } from '../../util/misc/boundingBoxFromPoints';
13	import {
14	  createRotateMatrix,
15	  createTranslateMatrix,
16	  composeMatrix,
17	  invertTransform,
18	  multiplyTransformMatrices,
19	  transformPoint,
20	  calcPlaneRotation,
