42	type TACoords = TCornerPoint;
43	
44	export class ObjectGeometry<EventSpec extends ObjectEvents = ObjectEvents>
45	  extends CommonMethods<EventSpec>
46	  implements
47	    Pick<ControlProps, 'padding'>,
48	    BaseProps,
49	    Pick<FillStrokeProps, 'strokeWidth' | 'strokeUniform'>
50	{
51	  // #region Geometry
52	
53	  declare padding: number;
54	
55	  /**
56	   * Describe object's corner position in scene coordinates.
57	   * The coordinates are derived from the following:
58	   * left, top, width, height, scaleX, scaleY, skewX, skewY, angle, strokeWidth.
59	   * The coordinates do not depend on viewport changes.
60	   * The coordinates get updated with {@link setCoords}.
61	   * You can calculate them without updating with {@link calcACoords()}
62	   */
63	  declare aCoords: TACoords;
64	
65	  /**
66	   * storage cache for object transform matrix
67	   */
68	  declare ownMatrixCache?: TMatrixCache;
69	
70	  /**
71	   * storage cache for object full transform matrix
72	   */
73	  declare matrixCache?: TMatrixCache;
74	
75	  /**
76	   * A Reference of the Canvas where the object is actually added
77	   * @type StaticCanvas | Canvas;
78	   * @default undefined
79	   * @private
80	   */
81	  declare canvas?: StaticCanvas | Canvas;
82	
83	  /**
84	   * @returns {number} x position according to object's originX property in canvas coordinate plane
85	   */
86	  getX(): number {
87	    return this.getXY().x;
88	  }
89	
90	  /**
91	   * @param {number} value x position according to object's originX property in canvas coordinate plane
92	   */
93	  setX(value: number) {
94	    this.setXY(this.getXY().setX(value));
95	  }
96	
97	  /**
98	   * @returns {number} y position according to object's originY property in canvas coordinate plane
99	   */
100	  getY(): number {
101	    return this.getXY().y;
102	  }
103	
104	  /**
105	   * @param {number} value y position according to object's originY property in canvas coordinate plane
106	   */
107	  setY(value: number) {
108	    this.setXY(this.getXY().setY(value));
109	  }
110	
111	  /**
112	   * @returns {number} x position according to object's originX property in parent's coordinate plane\
113	   * if parent is canvas then this property is identical to {@link getX}
114	   */
115	  getRelativeX(): number {
116	    return this.left;
117	  }
118	
119	  /**
120	   * @param {number} value x position according to object's originX property in parent's coordinate plane\
121	   * if parent is canvas then this method is identical to {@link setX}
122	   */
123	  setRelativeX(value: number) {
124	    this.left = value;
125	  }
126	
127	  /**
128	   * @returns {number} y position according to object's originY property in parent's coordinate plane\
129	   * if parent is canvas then this property is identical to {@link getY}
130	   */
131	  getRelativeY(): number {
132	    return this.top;
133	  }
134	
135	  /**
136	   * @param {number} value y position according to object's originY property in parent's coordinate plane\
137	   * if parent is canvas then this property is identical to {@link setY}
138	   */
139	  setRelativeY(value: number) {
140	    this.top = value;
141	  }
142	
143	  /**
144	   * @returns {Point} x position according to object's originX originY properties in canvas coordinate plane
145	   */
146	  getXY(): Point {
147	    const relativePosition = this.getRelativeXY();
148	    return this.group
149	      ? transformPoint(relativePosition, this.group.calcTransformMatrix())
150	      : relativePosition;
151	  }
152	
153	  /**
154	   * Set an object position to a particular point, the point is intended in absolute ( canvas ) coordinate.
155	   * You can specify originX and originY values,
156	   * that otherwise are the object's current values.
157	   * @example <caption>Set object's bottom left corner to point (5,5) on canvas</caption>
158	   * object.setXY(new Point(5, 5), 'left', 'bottom').
159	   * @param {Point} point position in scene coordinate plane
160	   * @param {TOriginX} [originX] Horizontal origin: 'left', 'center' or 'right'
161	   * @param {TOriginY} [originY] Vertical origin: 'top', 'center' or 'bottom'
162	   */
163	  setXY(point: Point, originX?: TOriginX, originY?: TOriginY) {
164	    if (this.group) {
165	      point = transformPoint(
166	        point,
167	        invertTransform(this.group.calcTransformMatrix()),
168	      );
169	    }
170	    this.setRelativeXY(point, originX, originY);
171	  }
172	
173	  /**
174	   * @returns {Point} x,y position according to object's originX originY properties in parent's coordinate plane
175	   */
176	  getRelativeXY(): Point {
177	    return new Point(this.left, this.top);
178	  }
179	
180	  /**
181	   * As {@link setXY}, but in current parent's coordinate plane (the current group if any or the canvas)
182	   * @param {Point} point position according to object's originX originY properties in parent's coordinate plane
183	   * @param {TOriginX} [originX] Horizontal origin: 'left', 'center' or 'right'
184	   * @param {TOriginY} [originY] Vertical origin: 'top', 'center' or 'bottom'
185	   */
186	  setRelativeXY(
187	    point: Point,
188	    originX: TOriginX = this.originX,
189	    originY: TOriginY = this.originY,
190	  ) {
191	    this.setPositionByOrigin(point, originX, originY);
192	  }
193	
194	  /**
195	   * @deprecated intermidiate method to be removed, do not use
196	   */
197	  protected isStrokeAccountedForInDimensions() {
198	    return false;
199	  }
200	
201	  /**
202	   * @return {Point[]} [tl, tr, br, bl] in the scene plane
203	   */
204	  getCoords(): Point[] {
205	    const { tl, tr, br, bl } =
206	      this.aCoords || (this.aCoords = this.calcACoords());
207	    const coords = [tl, tr, br, bl];
208	    if (this.group) {
209	      const t = this.group.calcTransformMatrix();
210	      return coords.map((p) => transformPoint(p, t));
211	    }
212	    return coords;
213	  }
214	
215	  /**
216	   * Checks if object intersects with the scene rect formed by tl and br
217	   */
218	  intersectsWithRect(tl: Point, br: Point): boolean {
219	    const intersection = Intersection.intersectPolygonRectangle(
220	      this.getCoords(),
221	      tl,
222	      br,
223	    );
224	    return intersection.status === 'Intersection';
225	  }
226	
227	  /**
228	   * Checks if object intersects with another object
229	   * @param {Object} other Object to test
230	   * @return {Boolean} true if object intersects with another object
231	   */
232	  intersectsWithObject(other: ObjectGeometry): boolean {
233	    const intersection = Intersection.intersectPolygonPolygon(
234	      this.getCoords(),
235	      other.getCoords(),
236	    );
237	
238	    return (
239	      intersection.status === 'Intersection' ||
240	      intersection.status === 'Coincident' ||
241	      other.isContainedWithinObject(this) ||
242	      this.isContainedWithinObject(other)
243	    );
244	  }
245	
246	  /**
247	   * Checks if object is fully contained within area of another object
248	   * @param {Object} other Object to test
249	   * @return {Boolean} true if object is fully contained within area of another object
250	   */
251	  isContainedWithinObject(other: ObjectGeometry): boolean {
252	    const points = this.getCoords();
253	    return points.every((point) => other.containsPoint(point));
254	  }
255	
256	  /**
257	   * Checks if object is fully contained within the scene rect formed by tl and br
258	   */
259	  isContainedWithinRect(tl: Point, br: Point): boolean {
260	    const { left, top, width, height } = this.getBoundingRect();
261	    return (
262	      left >= tl.x &&
263	      left + width <= br.x &&
264	      top >= tl.y &&
265	      top + height <= br.y
266	    );
267	  }
268	
269	  isOverlapping<T extends ObjectGeometry>(other: T): boolean {
270	    return (
271	      this.intersectsWithObject(other) ||
272	      this.isContainedWithinObject(other) ||
273	      other.isContainedWithinObject(this)
274	    );
275	  }
276	
277	  /**
278	   * Checks if point is inside the object
279	   * @param {Point} point Point to check against
280	   * @return {Boolean} true if point is inside the object
281	   */
282	  containsPoint(point: Point): boolean {
283	    return Intersection.isPointInPolygon(point, this.getCoords());
284	  }
285	
286	  /**
287	   * Checks if object is contained within the canvas with current viewportTransform
288	   * the check is done stopping at first point that appears on screen
289	   * @return {Boolean} true if object is fully or partially contained within canvas
290	   */
291	  isOnScreen(): boolean {
292	    if (!this.canvas) {
293	      return false;
294	    }
295	    const { tl, br } = this.canvas.vptCoords;
296	    const points = this.getCoords();
297	    // if some point is on screen, the object is on screen.
298	    if (
299	      points.some(
300	        (point) =>
301	          point.x <= br.x &&
302	          point.x >= tl.x &&
303	          point.y <= br.y &&
304	          point.y >= tl.y,
305	      )
306	    ) {
307	      return true;
308	    }
309	    // no points on screen, check intersection with absolute coordinates
310	    if (this.intersectsWithRect(tl, br)) {
311	      return true;
312	    }
313	    // check if the object is so big that it contains the entire viewport
314	    return this.containsPoint(tl.midPointFrom(br));
315	  }
316	
317	  /**
318	   * Checks if object is partially contained within the canvas with current viewportTransform
319	   * @return {Boolean} true if object is partially contained within canvas
320	   */
321	  isPartiallyOnScreen(): boolean {
322	    if (!this.canvas) {
323	      return false;
324	    }
325	    const { tl, br } = this.canvas.vptCoords;
326	    if (this.intersectsWithRect(tl, br)) {
327	      return true;
328	    }
329	    const allPointsAreOutside = this.getCoords().every(
330	      (point) =>
331	        (point.x >= br.x || point.x <= tl.x) &&
332	        (point.y >= br.y || point.y <= tl.y),
333	    );
334	    // check if the object is so big that it contains the entire viewport
335	    return allPointsAreOutside && this.containsPoint(tl.midPointFrom(br));
336	  }
337	
338	  /**
339	   * Returns coordinates of object's bounding rectangle (left, top, width, height)
340	   * the box is intended as aligned to axis of canvas.
341	   * @return {Object} Object with left, top, width, height properties
342	   */
343	  getBoundingRect(): TBBox {
344	    return makeBoundingBoxFromPoints(this.getCoords());
345	  }
346	
347	  /**
348	   * Returns width of an object's bounding box counting transformations
349	   * @todo shouldn't this account for group transform and return the actual size in canvas coordinate plane?
350	   * @return {Number} width value
351	   */
352	  getScaledWidth(): number {
353	    return this._getTransformedDimensions().x;
354	  }
355	
356	  /**
357	   * Returns height of an object bounding box counting transformations
358	   * @todo shouldn't this account for group transform and return the actual size in canvas coordinate plane?
359	   * @return {Number} height value
360	   */
361	  getScaledHeight(): number {
362	    return this._getTransformedDimensions().y;
363	  }
364	
365	  /**
366	   * Scales an object (equally by x and y)
367	   * @param {Number} value Scale factor
368	   * @return {void}
369	   */
370	  scale(value: number): void {
371	    this._set(SCALE_X, value);
372	    this._set(SCALE_Y, value);
373	    this.setCoords();
374	  }
375	
376	  /**
377	   * Scales an object to a given width, with respect to bounding box (scaling by x/y equally)
378	   * @param {Number} value New width value
379	   * @return {void}
380	   */
381	  scaleToWidth(value: number) {
382	    // adjust to bounding rect factor so that rotated shapes would fit as well
383	    const boundingRectFactor =
384	      this.getBoundingRect().width / this.getScaledWidth();
385	    return this.scale(value / this.width / boundingRectFactor);
386	  }
387	
388	  /**
389	   * Scales an object to a given height, with respect to bounding box (scaling by x/y equally)
390	   * @param {Number} value New height value
391	   * @return {void}
392	   */
393	  scaleToHeight(value: number) {
394	    // adjust to bounding rect factor so that rotated shapes would fit as well
395	    const boundingRectFactor =
396	      this.getBoundingRect().height / this.getScaledHeight();
397	    return this.scale(value / this.height / boundingRectFactor);
398	  }
399	
400	  getCanvasRetinaScaling() {
401	    return this.canvas?.getRetinaScaling() || 1;
402	  }
403	
404	  /**
405	   * Returns the object angle relative to canvas counting also the group property
406	   * @returns {TDegree}
407	   */
408	  getTotalAngle(): TDegree {
409	    return this.group
410	      ? radiansToDegrees(calcPlaneRotation(this.calcTransformMatrix()))
411	      : this.angle;
412	  }
413	
414	  /**
415	   * Retrieves viewportTransform from Object's canvas if available
416	   * @return {TMat2D}
417	   */
418	  getViewportTransform(): TMat2D {
419	    return this.canvas?.viewportTransform || (iMatrix.concat() as TMat2D);
420	  }
421	
422	  /**
423	   * Calculates the coordinates of the 4 corner of the bbox, in absolute coordinates.
424	   * those never change with zoom or viewport changes.
425	   * @return {TCornerPoint}
426	   */
427	  calcACoords(): TCornerPoint {
428	    const rotateMatrix = createRotateMatrix({ angle: this.angle }),
429	      { x, y } = this.getRelativeCenterPoint(),
430	      tMatrix = createTranslateMatrix(x, y),
431	      finalMatrix = multiplyTransformMatrices(tMatrix, rotateMatrix),
432	      dim = this._getTransformedDimensions(),
433	      w = dim.x / 2,
434	      h = dim.y / 2;
435	    return {
436	      // corners
437	      tl: transformPoint({ x: -w, y: -h }, finalMatrix),
438	      tr: transformPoint({ x: w, y: -h }, finalMatrix),
439	      bl: transformPoint({ x: -w, y: h }, finalMatrix),
440	      br: transformPoint({ x: w, y: h }, finalMatrix),
441	    };
442	  }
443	
444	  /**
445	   * Sets corner and controls position coordinates based on current angle, width and height, left and top.
446	   * aCoords are used to quickly find an object on the canvas.
447	   * See {@link https://github.com/fabricjs/fabric.js/wiki/When-to-call-setCoords} and {@link http://fabric5.fabricjs.com/fabric-gotchas}
448	   */
449	  setCoords(): void {
450	    this.aCoords = this.calcACoords();
451	  }
452	
453	  transformMatrixKey(skipGroup = false): number[] {
454	    let prefix: number[] = [];
455	    if (!skipGroup && this.group) {
456	      prefix = this.group.transformMatrixKey(skipGroup);
457	    }
458	    prefix.push(
459	      this.top,
460	      this.left,
461	      this.width,
462	      this.height,
463	      this.scaleX,
464	      this.scaleY,
465	      this.angle,
466	      this.strokeWidth,
467	      this.skewX,
468	      this.skewY,
469	      +this.flipX,
470	      +this.flipY,
471	      resolveOrigin(this.originX),
472	      resolveOrigin(this.originY),
473	    );
474	
475	    return prefix;
476	  }
477	
478	  /**
479	   * calculate transform matrix that represents the current transformations from the
480	   * object's properties.
481	   * @param {Boolean} [skipGroup] return transform matrix for object not counting parent transformations
482	   * There are some situation in which this is useful to avoid the fake rotation.
483	   * @return {TMat2D} transform matrix for the object
484	   */
485	  calcTransformMatrix(skipGroup = false): TMat2D {
486	    let matrix = this.calcOwnMatrix();
487	    if (skipGroup || !this.group) {
488	      return matrix;
489	    }
490	    const key = this.transformMatrixKey(skipGroup),
491	      cache = this.matrixCache;
492	    if (cache && cache.key.every((x, i) => x === key[i])) {
493	      return cache.value;
494	    }
495	    if (this.group) {
496	      matrix = multiplyTransformMatrices(
497	        this.group.calcTransformMatrix(false),
498	        matrix,
499	      );
500	    }
501	    this.matrixCache = {
502	      key,
503	      value: matrix,
504	    };
505	    return matrix;
506	  }
507	
508	  /**
509	   * calculate transform matrix that represents the current transformations from the
510	   * object's properties, this matrix does not include the group transformation
511	   * @return {TMat2D} transform matrix for the object
512	   */
513	  calcOwnMatrix(): TMat2D {
514	    const key = this.transformMatrixKey(true),
515	      cache = this.ownMatrixCache;
516	    if (cache && cache.key === key) {
517	      return cache.value;
518	    }
519	    const center = this.getRelativeCenterPoint(),
520	      options = {
521	        angle: this.angle,
522	        translateX: center.x,
523	        translateY: center.y,
524	        scaleX: this.scaleX,
525	        scaleY: this.scaleY,
526	        skewX: this.skewX,
527	        skewY: this.skewY,
528	        flipX: this.flipX,
529	        flipY: this.flipY,
530	      },
531	      value = composeMatrix(options);
532	    this.ownMatrixCache = {
533	      key,
534	      value,
535	    };
536	    return value;
537	  }
538	
539	  /**
540	   * Calculate object dimensions from its properties
541	   * @private
542	   * @returns {Point} dimensions
543	   */
544	  _getNonTransformedDimensions(): Point {
545	    return new Point(this.width, this.height).scalarAdd(this.strokeWidth);
546	  }
547	
548	  /**
549	   * Calculate object dimensions for controls box, including padding and canvas zoom.
550	   * and active selection
551	   * @private
552	   * @param {object} [options] transform options
553	   * @returns {Point} dimensions
554	   */
555	  _calculateCurrentDimensions(options?: any): Point {
556	    return this._getTransformedDimensions(options)
557	      .transform(this.getViewportTransform(), true)
558	      .scalarAdd(2 * this.padding);
559	  }
560	
561	  // #region Origin
562	
563	  declare top: number;
564	  declare left: number;
565	  declare width: number;
566	  declare height: number;
567	  declare flipX: boolean;
568	  declare flipY: boolean;
569	  declare scaleX: number;
570	  declare scaleY: number;
571	  declare skewX: number;
572	  declare skewY: number;
573	  /**
574	   * @deprecated please use 'center' as value in new projects
575	   * */
576	  declare originX: TOriginX;
577	  /**
578	   * @deprecated please use 'center' as value in new projects
579	   * */
580	  declare originY: TOriginY;
581	  declare angle: TDegree;
582	  declare strokeWidth: number;
583	  declare strokeUniform: boolean;
584	
585	  /**
586	   * Object containing this object.
587	   * can influence its size and position
588	   */
589	  declare group?: Group;
590	
591	  /**
592	   * Calculate object bounding box dimensions from its properties scale, skew.
593	   * This bounding box is aligned with object angle and not with canvas axis or screen.
594	   * @param {Object} [options]
595	   * @param {Number} [options.scaleX]
596	   * @param {Number} [options.scaleY]
597	   * @param {Number} [options.skewX]
598	   * @param {Number} [options.skewY]
599	   * @private
600	   * @returns {Point} dimensions
601	   */
602	  _getTransformedDimensions(options: any = {}): Point {
603	    const dimOptions = {
604	      // if scaleX or scaleY are negative numbers,
605	      // this will return dimensions that are negative.
606	      // and this will break assumptions around the codebase
607	      scaleX: this.scaleX,
608	      scaleY: this.scaleY,
609	      skewX: this.skewX,
610	      skewY: this.skewY,
611	      width: this.width,
612	      height: this.height,
613	      strokeWidth: this.strokeWidth,
614	      // TODO remove this spread. is visible in the performance inspection
615	      ...options,
616	    };
617	    // stroke is applied before/after transformations are applied according to `strokeUniform`
618	    const strokeWidth = dimOptions.strokeWidth;
619	    let preScalingStrokeValue = strokeWidth,
620	      postScalingStrokeValue = 0;
621	
622	    if (this.strokeUniform) {
623	      preScalingStrokeValue = 0;
624	      postScalingStrokeValue = strokeWidth;
625	    }
626	    const dimX = dimOptions.width + preScalingStrokeValue,
627	      dimY = dimOptions.height + preScalingStrokeValue,
628	      noSkew = dimOptions.skewX === 0 && dimOptions.skewY === 0;
629	    let finalDimensions;
630	    if (noSkew) {
631	      finalDimensions = new Point(
632	        dimX * dimOptions.scaleX,
633	        dimY * dimOptions.scaleY,
634	      );
635	    } else {
636	      finalDimensions = sizeAfterTransform(
637	        dimX,
638	        dimY,
639	        calcDimensionsMatrix(dimOptions),
640	      );
641	    }
642	
643	    return finalDimensions.scalarAdd(postScalingStrokeValue);
644	  }
645	
646	  /**
